<p class="small">Units face off in team missions. Your individual performance and teamwork both count!</p>`}const vb=$('varietyBtn');if(vb)vb.onclick=()=>{state.fans+=300;state.friend=Math.max(1,state.friend);toast('The clip went viral! +300 fans ✨');render()};const ab=$('adBtn');if(ab)ab.onclick=()=>{state.fans+=500;toast('Commercial deal secured! +500 fans 📺');render()}}
