function openFriend(){const roster=['MINHO · Dance captain','TAE · Vocal ace','JAE · Quiet songwriter','REN · Variety king'];let pick=roster[state.friend%roster.length];$('eventBody').innerHTML=`<div class="eyebrow">DORM CAM · FRIENDSHIP EVENT</div><h1>Make a connection ✦</h1><p>You find <b>${pick.split(' · ')[0]}</b> practicing after hours. ${pick.split(' · ')[1]} is already their reputation. How do you connect?</p><div class="modal-actions"><button class="primary" id="friendChoice">Practice together ♡</button><button class="secondary" id="cancelEvent">Save them a snack</button></div>`;showModal('event');$('friendChoice').onclick=()=>friendResult(pick);$('cancelEvent').onclick=()=>friendResult(pick)}
