window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='e'||e.key==='E')stageInteract();if(e.key===' '&&state.active)hitNote();state.keys[e.key]=true});window.addEventListener('keyup',e=>state.keys[e.key]=false);$('mobileInteract').onclick=stageInteract;document.querySelectorAll('[data-dir]').forEach(b=>{const key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();state.keys[key]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>state.keys[key]=false))});$('soundBtn').onclick=toggleSound;
let audio=null,musicTimer=null,noteIndex=0,beatStart=0,combo=0,perf=0,hits=0,gameTimer=null;
function toggleSound(){state.sound=!state.sound;$('soundBtn').textContent=state.sound?'♫ SOUND ON':'♫ SOUND OFF';if(state.sound&&state.started)startMusic();else stopMusic()}
function tone(freq,dur=.12,type='triangle',vol=.035){if(!state.sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
function startMusic(){stopMusic();let i=0,root=rounds[Math.min(state.round,3)].sound;const seq=[1,1.25,1.5,1.25,1.12,1.5,1.25,1.75];musicTimer=setInterval(()=>{tone(root*seq[i%8],.18,i%4===0?'square':'triangle',.022);if(i%2===0)tone(95,.07,'sine',.04);i++},250)}function stopMusic(){clearInterval(musicTimer)}
function startChallenge(){if(state.active)return;const r=rounds[Math.min(state.round,3)];state.active=true;noteIndex=0;combo=0;perf=0;hits=0;$('challengeEyebrow').textContent=`MISSION 0${state.round+1} · ${r.scene.toUpperCase()}`;$('challengeName').textContent=r.mission;$('challengeIntro').textContent=state.round===3?'The world is watching. Seven debut spots. Give them a finale to remember.':r.desc;$('judgeScore').textContent='—';$('combo').textContent='0';$('liveScore').textContent='0';$('challengeCount').textContent='NOTE 0 / 12';$('timing').textContent='Press SPACE / TAP when each note hits the cyan line!';$('rhythm').querySelectorAll('.note').forEach(n=>n.remove());$('startPerformance').style.display='';$('startPerformance').textContent='START PERFORMANCE ▶';showModal('challenge');if(state.sound)startMusic()}
function beginPerformance(){noteIndex=0;perf=0;combo=0;hits=0;$('startPerformance').style.display='none';beatStart=performance.now()+700;spawnNote();gameTimer=setInterval(()=>{let elapsed=performance.now()-beatStart,n=document.querySelector('.note');if(n){let p=elapsed/760;let x=96+p*144;n.style.left=x+'px';if(x>300&&!n.dataset.missed){n.dataset.missed='1';combo=0;$('combo').textContent='0'}}if(elapsed>1200){noteIndex++;if(noteIndex>=12){clearInterval(gameTimer);finishChallenge()}else{beatStart=performance.now();spawnNote()}}},16)}
function spawnNote(){let n=document.createElement('div');n.className='note'+(noteIndex%3===1?' alt':'');n.style.left='96px';$('rhythm').appendChild(n);$('challengeCount').textContent=`NOTE ${noteIndex+1} / 12`;tone(rounds[Math.min(state.round,3)].sound*(noteIndex%3===1?1.25:1),.1,'sine',.05)}
function hitNote(){if(!state.active||$('startPerformance').style.display!=='none')return;let elapsed=performance.now()-beatStart;let delta=Math.abs(elapsed-760);if(delta<300){let pts=delta<85?100:delta<170?70:45;perf+=pts;hits++;combo++;$('timing').textContent=delta<85?'PERFECT ✦':delta<170?'GREAT!':'GOOD';$('timing').style.color=delta<85?'#62f5e5':'#ffdf80';tone(delta<85?880:660,.1,'triangle',.07)}else{$('timing').textContent='MISS — find the beat!';combo=0} $('combo').textContent=combo;$('liveScore').textContent=perf;let n=document.querySelector('.note');if(n)n.style.opacity='.2'}
$('rhythm').addEventListener('pointerdown',()=>hitNote());$('startPerformance').onclick=beginPerformance;
function finishChallenge(){state.active=false;stopMusic();const r=rounds[Math.min(state.round,3)],accuracy=Math.round(hits/12*100),judge=Math.min(100,Math.round(perf/12));let teamBonus=state.friend?8:0,judges=Math.min(100,Math.round(judge*.72+accuracy*.28+teamBonus));let fans=Math.round(r.reward*(.35+accuracy/100*.65));state.fans+=fans;state.score+=Math.round(perf*.65+judges*5);state.wins++;let advancing=judges>=43||state.round===0;let finale=state.round===3&&judges>=45;$('eventBody').innerHTML=`<div class="eyebrow">${state.round===3?'WORLDWIDE LIVE FINALE':'MISSION COMPLETE · JUDGES & LIVE VOTES'}</div><h1>${finale?'YOU MADE THE DEBUT GROUP! ✦':judges>75?'A STAR IS BORN ✨':judges>50?'THE CROWD LOVES YOU!':'THE JUDGES HAVE SPOKEN'}</h1><p>Performance <b>${perf} points</b> · Accuracy <b>${accuracy}%</b> · Judge score <b>${judges}/100</b><br>Live audience: <b>+${fans.toLocaleString()} fans</b>${state.friend?'<br>Team chemistry bonus: <b>+'+teamBonus+' judge points</b>':''}</p><p>${state.round===3?(finale?'The audience votes are in! Jin joins the six trainees at the top. STARLINE is ready to debut.':'You gave it your all, but the final seven are decided by score. You can try another show run!'):advancing?'You advance to the next mission! The field narrows from '+r.people+' to '+rounds[state.round+1].people+' trainees.':'The judges want to see more. Get to know your team and go again!'}</p><div class="modal-actions"><button class="primary" id="resultContinue">${state.round===3?'CELEBRATE THE DEBUT ✦':advancing?'NEXT ROUND →':'RUN IT BACK ↻'}</button><button class="secondary" id="resultShow">VARIETY SHOW +300 FANS</button></div>`;showModal('event');$('resultShow').onclick=()=>{state.fans+=300;render();toast('Your backstage special is trending! +300 fans');};$('resultContinue').onclick=()=>{hideModal('event');if(advancing&&state.round<3){state.round++;setScene(state.round);toast(`Round ${state.round+1}: ${rounds[state.round].name}!`)}else if(state.round===3){$('eventBody').innerHTML='<div class="eyebrow">STAR//BOYS · DEBUT GROUP</div><h1>STARLINE ✦</h1><p>JIN · MINHO · TAE · JAE · REN · KAI · WOON</p><p>50 trainees walked in. Seven dreamers debut tonight. Thanks for being part of their story!</p><div class="modal-actions"><button class="primary" id="closeFinal">PLAY AGAIN</button></div>';showModal('event');$('closeFinal').onclick=()=>{state.round=0;state.score=0;state.fans=1240;state.friend=0;setScene(0);hideModal('event');render()}}render()}}
$('event').addEventListener('click',e=>{if(e.target===$('event'))hideModal('event')});$('challenge').addEventListener('click',e=>{if(e.target===$('challenge')&&!state.active){hideModal('challenge');state.active=false;stopMusic()}});
render();setScene(0);
</script></body></html>

