').innerHTML='<div class="eyebrow">STAR//BOYS · DEBUT GROUP</div><h1>STARLINE ✦</h1><p>JIN · MINHO · TAE · JAE · REN · KAI · WOON</p><p>50 trainees walked in. Seven dreamers debut tonight. Thanks for being part of their story!</p><div class="modal-actions"><button class="primary" id="closeFinal">PLAY AGAIN</button></div>';showModal('event');$('closeFinal').onclick=()=>{state.round=0;state.score=0;state.fans=1240;state.friend=0;setScene(0);hideModal('event');render()}}render()}}
